import polevl = require( './index' );


// TESTS //

// The function returns a number...
{
	const coef = [ 1.0, 2.0, 3.0 ];
	polevl( 2.0, coef, 2 ); // $ExpectType number
}

{
	const coef = new Float64Array( [ 1.0, 2.0, 3.0 ] );
	polevl( 0.5, coef, 2 ); // $ExpectType number
}

// The compiler throws an error if the function is provided invalid arguments...
{
	polevl( true, [ 1, 2 ], 1 ); // $ExpectError
	polevl( false, [ 1, 2 ], 1 ); // $ExpectError
	polevl( null, [ 1, 2 ], 1 ); // $ExpectError
	polevl( undefined, [ 1, 2 ], 1 ); // $ExpectError
	polevl( '5', [ 1, 2 ], 1 ); // $ExpectError
}

{
	polevl( 1.0, true, 1 ); // $ExpectError
	polevl( 1.0, false, 1 ); // $ExpectError
	polevl( 1.0, null, 1 ); // $ExpectError
	polevl( 1.0, undefined, 1 ); // $ExpectError
	polevl( 1.0, {}, 1 ); // $ExpectError
}

{
	polevl( 1.0, [ 1, 2 ], true ); // $ExpectError
	polevl( 1.0, [ 1, 2 ], false ); // $ExpectError
	polevl( 1.0, [ 1, 2 ], null ); // $ExpectError
	polevl( 1.0, [ 1, 2 ], undefined ); // $ExpectError
	polevl( 1.0, [ 1, 2 ], '2' ); // $ExpectError
}

// The compiler throws an error if the function is provided insufficient arguments...
{
	polevl(); // $ExpectError
	polevl( 1.0 ); // $ExpectError
	polevl( 1.0, [ 1, 2 ] ); // $ExpectError
}
